package ch.bbw.zork;import java.util.Arrays;import java.util.List;/** * Verwaltet alle gültigen Befehle des Zork-Spiels. */public class CommandWords {	private List<String> validCommands =			Arrays.asList("go", "quit", "help", "back", "map",					"take", "drop", "inventory");	/**	 * Prüft, ob ein Befehlswort gültig ist.	 *	 * @param commandWord zu prüfendes Befehlswort	 * @return true, wenn der Befehl gültig ist	 */	public boolean isCommand(String commandWord) {		return validCommands.stream()				.filter(c -> c.equals(commandWord))				.count() > 0;	}	/**	 * Gibt alle gültigen Befehle als Text zurück.	 *	 * @return alle gültigen Befehle	 */	public String showAll() {		return String.join(" ", validCommands);	}}